import re

def eval_expression(expr):
    # トークナイズ: 数字、演算子、括弧を分離する
    # \d+(\.\d+)? : 整数または小数
    # [+\-*/()] : 演算子と括弧
    tokens = re.findall(r'\d+(?:\.\d+)?|[+\-*/()]', expr)
    pos = 0

    def peek():
        """現在のトークンを返す（ポインタは進めない）"""
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        """現在のトークンを返し、ポインタを1つ進める"""
        nonlocal pos
        token = peek()
        pos += 1
        return token

    def parse_expression():
        """加算と減算を処理 (優先順位: 低)"""
        node = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                node += right
            else:
                node -= right
        return node

    def parse_term():
        """乗算と除算を処理 (優先順位: 中)"""
        node = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                node *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                node /= right
        return node

    def parse_factor():
        """単項演算子（負の数）と括弧を処理 (優先順位: 高)"""
        if peek() == '-':
            consume()  # '-' を消費
            return -parse_factor()  # 再帰的に処理して負にする
        if peek() == '+':
            consume()  # '+' を消費（無視して良い）
            return parse_factor()

        return parse_primary()

    def parse_primary():
        """数値または括弧の中身を処理"""
        token = consume()
        if token == '(':
            result = parse_expression()
            consume()  # ')' を消費
            return result
        else:
            return float(token)

    return parse_expression()

# --- テストケース ---
test_cases = [
    ("3 + 4 * (2 - 1)", 7),
    ("-3 + 5", 2),
    ("10 + -2", 8),
    ("2 * (3 + 4) * 2", 28),
    ("10 / 2 + 3", 8),
    ("10 / (2 + 3)", 2),
    ("-5 * (-2 - 3)", 25),
    ("10.5 + 0.5", 11),
]

for expr, expected in test_cases:
    result = eval_expression(expr)
    print(f"'{expr}' => {result} (Expected: {expected})")

# ゼロ除算のテスト
try:
    eval_expression("10 / 0")
except ZeroDivisionError as e:
    print(f"Caught expected error: {e}")
